
UPDATE products SET return_policy='7 天无理由退换，虚拟课程以未激活为准' WHERE product_id LIKE 'prod_px%' AND return_policy NOT LIKE '%退%';

-- Distinguish background catalog entries while retaining their realistic category/brand variation.
UPDATE products SET title = title || '（资料编号：' || product_id || '）' WHERE product_id LIKE 'prod_px%';
